	/**
	 * Default Constructor
	 */
    public ItemService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ItemEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ItemRepository.class) );
		this.validator		= applicationContext.getBean(ItemValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Item
	 */
		public Item createItem( CreateItemCommand command ) {

		Item entity = new Item();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setItemId( command.getItemId() );
            entity.setItemNumber( command.getItemNumber() );
            entity.setName( command.getName() );
            entity.setStandardCost( command.getStandardCost() );
            entity.setWeight( command.getWeight() );
            entity.setAsSerialControlled( command.getAsSerialControlled() );
            entity.setItemType( command.getItemType() );
            entity.setProcurementType( command.getProcurementType() );
            entity.setUnitOfMeasure( command.getUnitOfMeasure() );
            entity.setLifecycleStatus( command.getLifecycleStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Item {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateItemCommand
	 * @return		Item
	 */
	public Item updateItem( UpdateItemCommand command ) {

		Item entity = new Item();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setItemId( command.getItemId() );
            entity.setItemNumber( command.getItemNumber() );
            entity.setName( command.getName() );
            entity.setStandardCost( command.getStandardCost() );
            entity.setWeight( command.getWeight() );
            entity.setAsSerialControlled( command.getAsSerialControlled() );
            entity.setBusinessUnit( command.getBusinessUnit() );
            entity.setBoms( command.getBoms() );
            entity.setRoutings( command.getRoutings() );
            entity.setSuppliers( command.getSuppliers() );
            entity.setQualitySpecifications( command.getQualitySpecifications() );
            entity.setInventoryItems( command.getInventoryItems() );
            entity.setItemType( command.getItemType() );
            entity.setProcurementType( command.getProcurementType() );
            entity.setUnitOfMeasure( command.getUnitOfMeasure() );
            entity.setLifecycleStatus( command.getLifecycleStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Item {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteItemCommand
	 */
	public void delete( DeleteItemCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getItemId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Item {0} ", id );

	}

	/**
	 * Method to retrieve the Item via ItemFetchOneSummary
	 * @param 	summary ItemFetchOneSummary
	 * @return 	ItemFetchOneResponse
	 */
	public Item getItem( ItemFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ItemFetchOneSummary arg cannot be null" );

		Item entity = null;
		UUID id = summary.getItemId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Item using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Items
	 *
	 * @return 	List<Item>
	 */
    public List<Item> getAllItem() {
		List<Item> list = projector.findAll( new FindAllItemQuery() );
		return list;
	}

	/**
	 * assign BusinessUnit on Item
	 * @param		command AssignBusinessUnitToItemCommand
	 */
	public void assignBusinessUnit( AssignBusinessUnitToItemCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignBusinessUnit(command.getItemId(), command.getAssignment());

	}

